230	/* Recognise the recording.  Returns true and fills text on success. */
231	
232	static bool vr_stage_asr(char *text, size_t cap)
233	{
234	  struct vg_vc_info info;
235	  enum vg_vc_result rc;
236	  vela_req_ctl_t ctl;
237	
238	  ctl.deadline_ms = g_vr.s.deadline_ms;
239	  ctl.cancel = &g_vr.cancel;
240	
241	  while (vg_agent_round_voice_reserve() != 0)
242	    {
243	      if (g_vr.cancel) return false;
244	      if ((int32_t)(g_vr.s.deadline_ms - vr_now_ms()) <= 0)
245	        { vr_ui_error("等待查询超时，请重试"); return false; }
246	      usleep(20000);
247	    }
248	
249	  vr_ui_set_status("识别中");
250	  vr_ui_publish();
251	  vr_log_stage("asr_begin");
252	
253	  __atomic_fetch_add(&g_vr.asr_requests, 1, __ATOMIC_RELAXED);
254	
255	  /* The recording is still in RAM: upload it from there.  A file is only
256	   * read when a caller named one, which is the diagnostic path. */
257	
258	  {
259	    size_t bytes = 0;
260	    int16_t *pcm = NULL;
261	    if (g_vr.asr_src[0] != '\0')
262	      {
263	        uint32_t prep_t0 = vr_now_ms();
264	
265	        (void)vg_voice_finish_owned(g_vr.clip_generation, true);
266	        syslog(LOG_INFO, "[vgvoice] clip_prep src=file bytes=0 ms=%u\n",
267	               (unsigned)(vr_now_ms() - prep_t0));
268	        rc = vg_voice_cloud_asr(g_vr.asr_src, &ctl, text, cap, &info);
269	      }
270	    else
271	      {
272	        uint32_t prep_t0 = vr_now_ms();
273	        int take_rc = vg_voice_clip_take_owned(g_vr.clip_generation,
274	                                               &pcm, &bytes);
275	
276	        /* The take is the handoff the round waits on: recorder drain plus
277	         * the copy of up to 15.5 s of RAM audio.  bytes stays 0 when the
278	         * take failed, which the line then records as such. */
279	        syslog(LOG_INFO, "[vgvoice] clip_prep src=ram bytes=%u ms=%u\n",
280	               (unsigned)bytes, (unsigned)(vr_now_ms() - prep_t0));
281	        if (take_rc == 0)
282	          {
283	            rc = vg_voice_cloud_asr_buffer(pcm, bytes, &ctl, text, cap,
284	                                           &info);
285	            /* Volatile stores keep raw-audio cleanup before free
286	             * observable. */
287	            volatile unsigned char *wipe = (volatile unsigned char *)pcm;
288	            for (size_t i = 0; i < bytes; i++) wipe[i] = 0;
289	            free(pcm);
290	          }
291	        else
292	          {
293	            memset(&info, 0, sizeof(info));
294	            rc = VG_VC_IO;
295	          }
296	      }
297	  }
298	
299	  syslog(LOG_INFO, "[vgvoice] asr rc=%s status=%d req=%u resp=%u ms=%u\n",
300	         vg_vc_result_name(rc), info.status, (unsigned)info.req_bytes,
301	         (unsigned)info.resp_bytes, (unsigned)info.elapsed_ms);
302	  vr_log_stage("asr_end");
303	
304	  if (rc == VG_VC_CANCELLED)
305	    {
306	      return false;
307	    }
308	
309	  if (rc != VG_VC_OK)
310	    {
311	      if (rc == VG_VC_EMPTY)
312	        {
313	          vr_ui_error("没有听清，请再说一次");
314	        }
315	      else if (rc == VG_VC_TIMEOUT)
316	        {
317	          vr_ui_error("识别超时，请重试");
318	        }
319	      else if (rc == VG_VC_HTTP)
320	        {
321	          vr_ui_error("识别服务返回错误，请重试");
322	        }
323	      else
324	        {
325	          vr_ui_error("识别失败，请重试");
326	        }
327	
328	      return false;
329	    }
330	
331	  return true;
332	}
