334	/* Ask the on-board agent.  Returns true when the round finished inside the
335	 * budget and the answer is in display/speech. */
336	
337	static bool vr_wait_agent(uint32_t deadline_ms)
338	{
339	  for (;;)
340	    {
341	      enum vg_agent_round_state st;
342	
343	      /* Drive the channel here as well.  The HMI worker ticks every 100 ms,
344	       * but it can be busy with a report or advice write; a question that
345	       * sits QUEUED past the budget is indistinguishable from a model
346	       * timeout.  The submission guard keeps the two tickers from pushing
347	       * the same request twice. */
348	
349	      vg_agent_round_tick();
350	
351	      if (g_vr.cancel)
352	        {
353	          return false;
354	        }
355	
356	      st = vg_agent_round_state();
357	
358	      if (st == VG_AGENT_ROUND_DONE)
359	        {
360	          return true;
361	        }
362	
363	      if (st == VG_AGENT_ROUND_ERROR)
364	        {
365	          return false;
366	        }
367	
368	      if ((int32_t)(deadline_ms - vr_now_ms()) <= 0)
369	        {
370	          return false;
371	        }
372	
373	      usleep(VR_AGENT_POLL_MS * 1000);
374	    }
375	}
